// Fetch designation list and pick one different from last used
var baseUrl = pm.collectionVariables.get('baseUrl');
var token = pm.collectionVariables.get('authToken');

pm.sendRequest({
  url: baseUrl + '/api/core/designations',
  method: 'GET',
  header: { Authorization: 'Bearer ' + token }
}, function(err, res) {
  var fallback = { id: 4, name: 'Senior Software Engineer' };
  if (err || res.code !== 200) {
    pm.variables.set('desigId', String(fallback.id));
    pm.variables.set('desigName', fallback.name);
    return;
  }
  var body = res.json();
  var list = Array.isArray(body) ? body : (body.data || body.items || []);
  var active = list.filter(function(d) { return d.status !== false && d.id; });
  var lastId = parseInt(pm.collectionVariables.get('lastDesignationId') || '0');
  var pick = active.find(function(d) { return d.id !== lastId; }) || active[0] || fallback;
  pm.collectionVariables.set('lastDesignationId', String(pick.id));
  pm.variables.set('desigId', String(pick.id));
  pm.variables.set('desigName', (pick.name || '').replace(/"/g, ''));
});

