// Set transition date 1 year ahead so API never rejects it as past
var d = new Date(); d.setFullYear(d.getFullYear() + 1);
pm.variables.set('leaveIssuerDate', d.toISOString().split('T')[0]);
pm.sendRequest({
  url: baseUrl + '/api/core/users?sortBy=firstName&order=ASC&size=30',
  method: 'GET',
  header: { Authorization: 'Bearer ' + token }
}, function(err, res) {
  var fallbackId    = 13315;
  var fallbackEmail = 'palisthashrestha@lftechnology.com';
  if (err || res.code !== 200) {
    pm.variables.set('leaveIssuerId',    String(fallbackId));
    pm.variables.set('leaveIssuerEmail', fallbackEmail);
    return;
  }
  var body = res.json();
  var arr  = Array.isArray(body) ? body : (body.data ? (Array.isArray(body.data) ? body.data : (body.data.data || [])) : []);
  var lastId = parseInt(pm.collectionVariables.get('lastLeaveIssuerId') || '0');
  var candidates = arr.filter(function(u) { return u.id && u.id !== myId && u.id !== lastId; });
  var pick = candidates.length ? candidates[0] : arr.find(function(u) { return u.id && u.id !== myId; });
  if (pick) {
    pm.collectionVariables.set('lastLeaveIssuerId', String(pick.id));
    pm.variables.set('leaveIssuerId',    String(pick.id));
    pm.variables.set('leaveIssuerEmail', pick.email || fallbackEmail);
  } else {
    pm.variables.set('leaveIssuerId',    String(fallbackId));
    pm.variables.set('leaveIssuerEmail', fallbackEmail);
  }
});

