// Fetch users list and pick a different manager from last used
var baseUrl = pm.collectionVariables.get('baseUrl');
var token = pm.collectionVariables.get('authToken');
var myId = parseInt(pm.collectionVariables.get('userId') || '0');

pm.sendRequest({
  url: baseUrl + '/api/core/users?sortBy=firstName&order=ASC&size=50',
  method: 'GET',
  header: { Authorization: 'Bearer ' + token }
}, function(err, res) {
  var fallbackId = 552;
  if (err || res.code !== 200) {
    pm.variables.set('managerId', String(fallbackId));
    return;
  }
  var body = res.json();
  var arr = Array.isArray(body) ? body : (body.data ? (Array.isArray(body.data) ? body.data : (body.data.data || [])) : []);
  var lastId = parseInt(pm.collectionVariables.get('lastManagerId') || '0');
  // Pick someone who is not us and not the last-used manager
  var candidates = arr.filter(function(u) { return u.id && u.id !== myId && u.id !== lastId; });
  var pick = candidates.length ? candidates[0] : arr.find(function(u) { return u.id && u.id !== myId; });
  var chosenId = pick ? pick.id : fallbackId;
  pm.collectionVariables.set('lastManagerId', String(chosenId));
  pm.variables.set('managerId', String(chosenId));
});

